import{_ as t,o as a,c as p,a4 as r}from"./chunks/framework.C3unmAF4.js";const i=JSON.parse('{"title":"兴农有“数”——重庆智慧农业一线见闻","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"兴农有“数”——重庆智慧农业一线见闻","date":"2026-06-25T00:00:00.000Z","source":"农业农村部智慧农业专题","category":"news","link":"https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202606/t20260612_6484949.htm","summary":"螺丝椒挂满枝头,番茄红得透亮……初夏,走进\\n重庆市开州区鲁渝(寿光)蔬菜现代产业园\\n,智慧大棚内瓜菜飘香。\\n“现在靠手机一键管棚,种植户当上了‘甩手掌柜’,省时又省力。”鲁渝蔬菜智慧大棚技术负责人董建林掏出手机轻点几下,遮阳网缓缓展开、滴灌系统应声启动,光照、温湿度、二氧化碳浓度等关键数据一屏掌控。\\n“过去,干旱来了急,霜冻来了愁,暴雨来了直跺脚。现在好了,再不用看天气的脸色了。...\\n","contentHash":"87f9ebaee99fcb283a0756663f3b3785","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-06-25-兴农有-数-重庆智慧农业一线见闻.md","filePath":"news/2026-06-25-兴农有-数-重庆智慧农业一线见闻.md"}'),_={name:"news/2026-06-25-兴农有-数-重庆智慧农业一线见闻.md"};function n(s,e,o,l,d,c){return a(),p("div",null,[...e[0]||(e[0]=[r('<h1 id="兴农有-数-——重庆智慧农业一线见闻" tabindex="-1">兴农有“数”——重庆智慧农业一线见闻 <a class="header-anchor" href="#兴农有-数-——重庆智慧农业一线见闻" aria-label="Permalink to &quot;兴农有“数”——重庆智慧农业一线见闻&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202606/t20260612_6484949.htm" target="_blank" rel="noreferrer">农业农村部智慧农业专题</a><br> 日期: 2026-06-25 摘要: 螺丝椒挂满枝头,番茄红得透亮……初夏,走进 重庆市开州区鲁渝(寿光)蔬菜现代产业园 ,智慧大棚内瓜菜飘香。 “现在靠手机一键管棚,种植户当上了‘甩手掌柜’,省时又省力。”鲁渝蔬菜智慧大棚技术负责人董建林掏出手机轻点几下,遮阳网缓缓展开、滴灌系统应声启动,光照、温湿度、二氧化碳浓度等关键数据一屏掌控。 “过去,干旱来了急,霜冻来了愁,暴雨来了直跺脚。现在好了,再不用看天气的脸色了。...</p></blockquote><p>“现在靠手机一键管棚,种植户当上了‘甩手掌柜’,省时又省力。”鲁渝蔬菜智慧大棚技术负责人董建林掏出手机轻点几下,遮阳网缓缓展开、滴灌系统应声启动,光照、温湿度、二氧化碳浓度等关键数据一屏掌控。</p><p>“过去,干旱来了急,霜冻来了愁,暴雨来了直跺脚。现在好了,再不用看天气的脸色了。”管着20个大棚、60多亩菜地的种植户刘伟说,去年遇到极端天气,他的智慧大棚未受波及,产量和效益比露天地高出三四倍。</p><p>数据向内管生产,向外通销路。大棚里刚包装好的螺丝椒,二维码格外醒目。“从育苗到采收,全过程有记录、可溯源。消费者扫一扫,生长数据一目了然,靠着这份绿色安全,今年已有50吨蔬菜直供粤港澳大湾区。”董建林说。</p><p>重庆市开州区鲁渝(寿光)蔬菜现代产业园的智慧大棚。(受访者供图)</p><p>在重庆市璧山区果琳生态番茄小镇,一台AI机器狗正沿垄沟巡行,识别疫病、测量果径,联动系统驱动水肥温湿调控。不远处,AI智慧农业运营平台大屏幕上,每一棚的农资、农事、产量、用工实时呈现。</p><p>番茄小镇引进了70多个番茄品种,不同品种的果形、甜度、上市时间各不相同,管理方案也各有差异。“选什么种、怎么种,最后卖给谁,每一步都有数据支撑。”基地负责人秦洪伟说,靠着AI辅助决策,基地优质果率提升至90%以上,单位面积产值提升了20%,综合成本降低了10%。</p><p>数据跑起来,农户也努力“奔跑”。番茄小镇培养新型职业农民200余人,从品牌落地、种植规划到技术执行和渠道销售,实现模块化种植。“从会种地到‘慧’种地,我们培养的新农人,不仅懂农时,更会用AI看数据、管生产、找市场。”秦洪伟说。</p><p>重庆市璧山区果琳生态番茄小镇内AI机器狗正在巡检番茄。新华社记者郑世昌 摄</p><p>近年来,重庆加快提升农业科技创新效能,AI技术下沉田间地头,成了农户的“新农具”。</p><p>眼下,巴南区石龙镇的水稻正值病虫害防治关键期。巴南区农业农村委员会信息中心主任杨刚说,重庆属于丘陵地带,巴掌地多,农户分散。过去庄稼生了病,要么跑镇上找农资店,说不清症状,买不对药;要么干脆不管,等病害蔓延开来,收成打了折扣。</p><p>如今,通过乡村振兴(重庆)数字产业研究院打造的“AI庄稼医院”,农户拍照上传发病点,1分钟内初诊,农技专家5分钟内人工复核,一张包含用药方案、就近合规农资店和售后机构的“电子处方”直接推到农户手机上。</p><p>乡村振兴(重庆)数字产业研究院技术经理左杭介绍,团队通过数据增强、迁移学习及多维度标签体系,让AI参考当地当季气候数据进行诊断。未来,可实现区域化诊断和病虫害趋势预警,从治病走向防病。截至2026年5月,“AI庄稼医院”已覆盖巴南区26个行政村、3500余户,累计问诊近3000次,识别120余种病虫害,准确率超90%。研究院同步打造智慧育苗平台,对育苗全过程智能化管控,育苗效率提升35%,死苗率下降3%,综合成本降低28%。</p><p>“帮农户减损增收,算法才真正‘落进’了泥土里。”左杭说。(记者郑世昌、肖瑶)</p><p><a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202606/t20260612_6484949.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',16)])])}const h=t(_,[["render",n]]);export{i as __pageData,h as default};
